[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;1,400&display=swap" rel="stylesheet" />
  <style>
    /* =====================================================
       DESIGN TOKENS — OKLCH COLOR SYSTEM
    ===================================================== */
    :root {
      /* Brand palette */
      --brand-black:   oklch(10% 0.01 270);
      --brand-purple:  oklch(50% 0.28 295);
      --brand-orange:  oklch(67% 0.21 46);

      /* Gradient stops */
      --grad-purple-start: oklch(50% 0.28 295);
      --grad-magenta:      oklch(55% 0.27 330);
      --grad-orange-end:   oklch(67% 0.21 46);

      /* Neutral scale */
      --neutral-50:  oklch(98.5% 0.002 265);
      --neutral-100: oklch(96%   0.004 265);
      --neutral-200: oklch(91%   0.006 265);
      --neutral-300: oklch(83%   0.008 265);
      --neutral-400: oklch(70%   0.01  265);
      --neutral-500: oklch(57%   0.01  265);
      --neutral-600: oklch(44%   0.01  265);
      --neutral-700: oklch(33%   0.01  265);
      --neutral-800: oklch(22%   0.01  265);
      --neutral-900: oklch(13%   0.01  265);

      /* Semantic */
      --text-primary:   var(--neutral-900);
      --text-secondary: var(--neutral-600);
      --text-muted:     var(--neutral-400);
      --bg-page:        var(--neutral-50);
      --bg-card:        #ffffff;
      --border:         var(--neutral-200);

      /* Safety section tint */
      --safety-bg: oklch(96% 0.015 295);

      /* Spacing scale (8-pt base) */
      --sp-1: 0.25rem;   /* 4px  */
      --sp-2: 0.5rem;    /* 8px  */
      --sp-3: 0.75rem;   /* 12px */
      --sp-4: 1rem;      /* 16px */
      --sp-5: 1.25rem;   /* 20px */
      --sp-6: 1.5rem;    /* 24px */
      --sp-8: 2rem;      /* 32px */
      --sp-10: 2.5rem;   /* 40px */
      --sp-12: 3rem;     /* 48px */
      --sp-16: 4rem;     /* 64px */
      --sp-20: 5rem;     /* 80px */
      --sp-24: 6rem;     /* 96px */

      /* Radius */
      --radius-sm: 8px;
      --radius-md: 14px;
      --radius-lg: 24px;
      --radius-xl: 36px;
      --radius-full: 9999px;

      /* Shadows */
      --shadow-sm: 0 1px 3px oklch(10% 0.01 265 / 0.08), 0 1px 2px oklch(10% 0.01 265 / 0.06);
      --shadow-md: 0 4px 16px oklch(10% 0.01 265 / 0.10), 0 2px 6px oklch(10% 0.01 265 / 0.06);
      --shadow-lg: 0 12px 40px oklch(10% 0.01 265 / 0.14), 0 4px 16px oklch(10% 0.01 265 / 0.08);
      --shadow-card: 0 2px 8px oklch(10% 0.01 265 / 0.07), 0 8px 32px oklch(10% 0.01 265 / 0.07);

      /* Typography */
      --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;

      /* Transitions */
      --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
      --ease-in-out: cubic-bezier(0.45, 0, 0.55, 1);
    }

    /* =====================================================
       RESET & BASE
    ===================================================== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    html {
      scroll-behavior: smooth;
      -webkit-text-size-adjust: 100%;
    }

    body {
      font-family: var(--font-sans);
      font-size: 1rem;
      line-height: 1.6;
      color: var(--text-primary);
      background: var(--bg-page);
      overflow-x: hidden;
    }

    img { display: block; max-width: 100%; }
    a { color: inherit; text-decoration: none; }
    button { cursor: pointer; font-family: inherit; border: none; background: none; }
    ul, ol { list-style: none; }

    /* =====================================================
       UTILITY CLASSES
    ===================================================== */
    .container {
      width: min(100%, 1200px);
      margin-inline: auto;
      padding-inline: var(--sp-6);
    }

    .gradient-text {
      background: linear-gradient(135deg, var(--brand-purple) 0%, var(--grad-magenta) 50%, var(--brand-orange) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .sr-only {
      position: absolute; width: 1px; height: 1px;
      padding: 0; margin: -1px; overflow: hidden;
      clip: rect(0,0,0,0); white-space: nowrap; border: 0;
    }

    /* =====================================================
       HEADER / NAV
    ===================================================== */
    .site-header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: oklch(98.5% 0.002 265 / 0.92);
      backdrop-filter: blur(20px) saturate(180%);
      -webkit-backdrop-filter: blur(20px) saturate(180%);
      border-bottom: 1px solid var(--border);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
      gap: var(--sp-6);
    }

    /* Logo */
    .logo {
      display: flex;
      align-items: center;
      gap: var(--sp-2);
      font-weight: 800;
      font-size: 1.25rem;
      letter-spacing: -0.02em;
      color: var(--brand-black);
      flex-shrink: 0;
    }

    .logo-icon {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--brand-purple), var(--brand-orange));
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 18px;
      height: 18px;
      fill: #fff;
    }

    /* Desktop nav */
    .nav-desktop {
      display: flex;
      align-items: center;
      gap: var(--sp-1);
    }

    .nav-desktop a {
      padding: var(--sp-2) var(--sp-3);
      font-size: 0.9rem;
      font-weight: 500;
      color: var(--text-secondary);
      border-radius: var(--radius-sm);
      transition: color 0.2s, background 0.2s;
    }

    .nav-desktop a:hover {
      color: var(--text-primary);
      background: var(--neutral-100);
    }

    /* Header right */
    .header-actions {
      display: flex;
      align-items: center;
      gap: var(--sp-3);
    }

    .btn-login {
      padding: var(--sp-2) var(--sp-5);
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--brand-black);
      border: 1.5px solid var(--neutral-300);
      border-radius: var(--radius-full);
      background: var(--bg-card);
      transition: border-color 0.2s, box-shadow 0.2s, transform 0.15s;
    }

    .btn-login:hover {
      border-color: var(--brand-purple);
      box-shadow: 0 0 0 3px oklch(50% 0.28 295 / 0.12);
      transform: translateY(-1px);
    }

    /* Hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      justify-content: center;
      gap: 5px;
      width: 40px;
      height: 40px;
      padding: var(--sp-2);
      border-radius: var(--radius-sm);
      transition: background 0.2s;
    }

    .hamburger:hover { background: var(--neutral-100); }

    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--text-primary);
      border-radius: 2px;
      transition: transform 0.3s var(--ease-out), opacity 0.3s;
    }

    /* Hamburger open state */
    .hamburger.is-open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.is-open span:nth-child(2) { opacity: 0; transform: scaleX(0); }
    .hamburger.is-open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* Mobile nav overlay */
    .nav-mobile {
      display: none;
      position: fixed;
      inset: 64px 0 0 0;
      background: var(--bg-card);
      z-index: 99;
      padding: var(--sp-6);
      overflow-y: auto;
      border-top: 1px solid var(--border);
      transform: translateY(-8px);
      opacity: 0;
      pointer-events: none;
      transition: transform 0.3s var(--ease-out), opacity 0.3s;
    }

    .nav-mobile.is-open {
      transform: translateY(0);
      opacity: 1;
      pointer-events: auto;
    }

    .nav-mobile a {
      display: block;
      padding: var(--sp-4) 0;
      font-size: 1.1rem;
      font-weight: 600;
      color: var(--text-primary);
      border-bottom: 1px solid var(--border);
      transition: color 0.2s;
    }

    .nav-mobile a:hover { color: var(--brand-purple); }

    .nav-mobile .btn-login-mobile {
      display: inline-flex;
      margin-top: var(--sp-6);
      padding: var(--sp-3) var(--sp-8);
      font-size: 1rem;
      font-weight: 700;
      color: #fff;
      background: linear-gradient(135deg, var(--brand-purple), var(--brand-orange));
      border-radius: var(--radius-full);
    }

    /* =====================================================
       HERO SECTION
    ===================================================== */
    .hero {
      position: relative;
      overflow: hidden;
      padding: var(--sp-24) 0 var(--sp-20);
      background: var(--bg-page);
    }

    /* Background blobs */
    .hero::before,
    .hero::after {
      content: '';
      position: absolute;
      border-radius: 50%;
      filter: blur(80px);
      pointer-events: none;
      z-index: 0;
    }

    .hero::before {
      width: 600px;
      height: 600px;
      top: -200px;
      right: -150px;
      background: radial-gradient(circle, oklch(50% 0.28 295 / 0.18) 0%, transparent 70%);
    }

    .hero::after {
      width: 500px;
      height: 500px;
      bottom: -150px;
      left: -100px;
      background: radial-gradient(circle, oklch(67% 0.21 46 / 0.15) 0%, transparent 70%);
    }

    .hero-inner {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: var(--sp-16);
      align-items: center;
    }

    .hero-content { max-width: 560px; }

    .hero-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: var(--sp-2);
      padding: var(--sp-1) var(--sp-4);
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--brand-purple);
      background: oklch(50% 0.28 295 / 0.08);
      border: 1px solid oklch(50% 0.28 295 / 0.2);
      border-radius: var(--radius-full);
      margin-bottom: var(--sp-5);
    }

    .hero-title {
      font-size: clamp(2.4rem, 5vw, 3.75rem);
      font-weight: 800;
      line-height: 1.08;
      letter-spacing: -0.03em;
      color: var(--text-primary);
      margin-bottom: var(--sp-6);
    }

    .hero-subtitle {
      font-size: 1.1rem;
      color: var(--text-secondary);
      margin-bottom: var(--sp-8);
      max-width: 460px;
      line-height: 1.7;
    }

    .hero-cta-row {
      display: flex;
      align-items: center;
      gap: var(--sp-4);
      flex-wrap: wrap;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: var(--sp-2);
      padding: var(--sp-4) var(--sp-8);
      font-size: 1rem;
      font-weight: 700;
      color: #fff;
      background: linear-gradient(135deg, var(--brand-purple) 0%, var(--grad-magenta) 60%, var(--brand-orange) 100%);
      border-radius: var(--radius-full);
      box-shadow: 0 4px 20px oklch(50% 0.28 295 / 0.35);
      transition: transform 0.2s var(--ease-out), box-shadow 0.2s;
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 32px oklch(50% 0.28 295 / 0.45);
    }

    .btn-primary:active { transform: translateY(0); }

    .hero-learn-more {
      font-size: 0.95rem;
      font-weight: 600;
      color: var(--text-secondary);
      display: inline-flex;
      align-items: center;
      gap: var(--sp-1);
      transition: color 0.2s;
    }

    .hero-learn-more:hover { color: var(--brand-purple); }

    /* Hero visual */
    .hero-visual {
      position: relative;
      display: flex;
      justify-content: center;
    }

    .hero-phone-mockup {
      width: 280px;
      aspect-ratio: 9/19;
      background: var(--brand-black);
      border-radius: 40px;
      box-shadow: var(--shadow-lg), 0 0 0 8px oklch(10% 0.01 270 / 0.06);
      position: relative;
      overflow: hidden;
      transform: perspective(800px) rotateY(-8deg) rotateX(2deg);
    }

    .phone-screen {
      position: absolute;
      inset: 8px;
      border-radius: 32px;
      overflow: hidden;
      background: linear-gradient(160deg, oklch(50% 0.28 295) 0%, oklch(55% 0.27 330) 40%, oklch(67% 0.21 46) 100%);
    }

    .phone-notch {
      position: absolute;
      top: 14px;
      left: 50%;
      transform: translateX(-50%);
      width: 80px;
      height: 10px;
      background: var(--brand-black);
      border-radius: var(--radius-full);
      z-index: 2;
    }

    .phone-content {
      padding: 50px var(--sp-4) var(--sp-4);
      display: flex;
      flex-direction: column;
      gap: var(--sp-3);
      height: 100%;
    }

    .phone-story-row {
      display: flex;
      gap: var(--sp-2);
    }

    .phone-story-avatar {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 2px solid rgba(255,255,255,0.8);
      flex-shrink: 0;
      overflow: hidden;
    }

    .phone-story-avatar:nth-child(1) { background: linear-gradient(135deg, #ff6b6b, #ffd93d); }
    .phone-story-avatar:nth-child(2) { background: linear-gradient(135deg, #6bcb77, #4d96ff); }
    .phone-story-avatar:nth-child(3) { background: linear-gradient(135deg, #ff6b9d, #c77dff); }

    .phone-post {
      background: rgba(255,255,255,0.15);
      backdrop-filter: blur(10px);
      border-radius: 16px;
      overflow: hidden;
      flex: 1;
    }

    .phone-post-img {
      height: 100px;
      background: linear-gradient(135deg, rgba(255,255,255,0.25) 0%, rgba(255,255,255,0.05) 100%);
    }

    .phone-post-bar {
      padding: var(--sp-2) var(--sp-3);
      display: flex;
      align-items: center;
      gap: var(--sp-2);
    }

    .phone-post-dot {
      width: 24px;
      height: 24px;
      border-radius: 50%;
      background: rgba(255,255,255,0.4);
    }

    .phone-post-lines {
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 3px;
    }

    .phone-post-line {
      height: 5px;
      border-radius: 3px;
      background: rgba(255,255,255,0.3);
    }

    .phone-post-line:last-child { width: 60%; }

    /* Floating badges */
    .hero-badge {
      position: absolute;
      background: var(--bg-card);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-md);
      padding: var(--sp-3) var(--sp-4);
      display: flex;
      align-items: center;
      gap: var(--sp-2);
      font-size: 0.8rem;
      font-weight: 700;
    }

    .hero-badge-1 {
      top: 10%;
      left: -10%;
      color: var(--brand-purple);
    }

    .hero-badge-2 {
      bottom: 18%;
      right: -8%;
      color: var(--brand-orange);
    }

    .badge-icon {
      width: 28px;
      height: 28px;
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
    }

    .badge-icon-purple { background: oklch(50% 0.28 295 / 0.12); }
    .badge-icon-orange { background: oklch(67% 0.21 46 / 0.12); }

    /* =====================================================
       FEATURES SECTION
    ===================================================== */
    .features {
      padding: var(--sp-24) 0;
      background: var(--bg-card);
    }

    .section-label {
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--brand-purple);
      margin-bottom: var(--sp-3);
    }

    .section-heading {
      font-size: clamp(1.75rem, 3.5vw, 2.75rem);
      font-weight: 800;
      letter-spacing: -0.025em;
      line-height: 1.15;
      color: var(--text-primary);
      margin-bottom: var(--sp-5);
      max-width: 700px;
    }

    .section-body {
      font-size: 1.05rem;
      color: var(--text-secondary);
      max-width: 640px;
      line-height: 1.75;
      margin-bottom: var(--sp-6);
    }

    .link-arrow {
      display: inline-flex;
      align-items: center;
      gap: var(--sp-2);
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--brand-purple);
      transition: gap 0.2s;
    }

    .link-arrow:hover { gap: var(--sp-3); }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: var(--sp-4);
      margin-top: var(--sp-10);
    }

    .feature-card {
      background: var(--bg-page);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: var(--sp-6);
      transition: transform 0.25s var(--ease-out), box-shadow 0.25s;
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .feature-icon {
      width: 48px;
      height: 48px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 22px;
      margin-bottom: var(--sp-4);
    }

    .feature-icon-purple { background: oklch(50% 0.28 295 / 0.1); }
    .feature-icon-orange { background: oklch(67% 0.21 46 / 0.1); }
    .feature-icon-magenta { background: oklch(55% 0.27 330 / 0.1); }
    .feature-icon-teal { background: oklch(60% 0.15 200 / 0.1); }

    .feature-name {
      font-size: 1rem;
      font-weight: 700;
      color: var(--text-primary);
      margin-bottom: var(--sp-2);
    }

    .feature-desc {
      font-size: 0.875rem;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* =====================================================
       SAFETY SECTION
    ===================================================== */
    .safety {
      padding: var(--sp-24) 0;
      background: var(--safety-bg);
      position: relative;
      overflow: hidden;
    }

    .safety::before {
      content: '';
      position: absolute;
      width: 400px;
      height: 400px;
      top: -120px;
      right: -80px;
      border-radius: 50%;
      background: radial-gradient(circle, oklch(50% 0.28 295 / 0.1) 0%, transparent 70%);
      pointer-events: none;
    }

    .safety-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: var(--sp-16);
      align-items: center;
      position: relative;
      z-index: 1;
    }

    .safety-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: var(--sp-4);
    }

    .safety-card {
      background: var(--bg-card);
      border-radius: var(--radius-lg);
      padding: var(--sp-5);
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--border);
      transition: transform 0.25s var(--ease-out), box-shadow 0.25s;
    }

    .safety-card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow-md);
    }

    .safety-card:first-child {
      grid-column: span 2;
      display: flex;
      align-items: center;
      gap: var(--sp-4);
    }

    .safety-card-icon {
      width: 44px;
      height: 44px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      flex-shrink: 0;
      background: oklch(50% 0.28 295 / 0.1);
    }

    .safety-card-label {
      font-size: 0.875rem;
      font-weight: 700;
      color: var(--text-primary);
    }

    .safety-card-sub {
      font-size: 0.8rem;
      color: var(--text-secondary);
      margin-top: 2px;
    }

    /* =====================================================
       CREATORS SECTION
    ===================================================== */
    .creators {
      padding: var(--sp-24) 0;
      background: var(--brand-black);
      color: #fff;
      position: relative;
      overflow: hidden;
    }

    .creators::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 60% 50% at 80% 50%, oklch(50% 0.28 295 / 0.3) 0%, transparent 60%),
        radial-gradient(ellipse 40% 60% at 20% 80%, oklch(67% 0.21 46 / 0.2) 0%, transparent 60%);
      pointer-events: none;
    }

    .creators-inner {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: var(--sp-16);
      align-items: center;
    }

    .creators .section-label { color: var(--brand-orange); }

    .creators .section-heading { color: #fff; }

    .creators .section-body { color: oklch(80% 0.02 265); }

    .creators .link-arrow {
      color: var(--brand-orange);
    }

    .creators-stats {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: var(--sp-4);
    }

    .stat-card {
      background: oklch(20% 0.01 270 / 0.6);
      border: 1px solid oklch(100% 0 0 / 0.08);
      backdrop-filter: blur(10px);
      border-radius: var(--radius-lg);
      padding: var(--sp-6);
    }

    .stat-number {
      font-size: 2.25rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1;
      margin-bottom: var(--sp-2);
    }

    .stat-number.gradient-text {
      background: linear-gradient(135deg, var(--brand-purple), var(--brand-orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .stat-label {
      font-size: 0.875rem;
      color: oklch(70% 0.02 265);
      font-weight: 500;
    }

    /* =====================================================
       TAGLINE BANNER
    ===================================================== */
    .tagline-banner {
      padding: var(--sp-16) 0;
      background: linear-gradient(135deg, var(--brand-purple) 0%, var(--grad-magenta) 50%, var(--brand-orange) 100%);
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .tagline-banner::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Ccircle cx='30' cy='30' r='2'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }

    .tagline-text {
      position: relative;
      font-size: clamp(1.75rem, 4vw, 3rem);
      font-weight: 800;
      color: #fff;
      letter-spacing: -0.025em;
      line-height: 1.2;
    }

    /* =====================================================
       NEWS SECTION
    ===================================================== */
    .news {
      padding: var(--sp-24) 0;
      background: var(--bg-page);
    }

    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: var(--sp-10);
      gap: var(--sp-4);
      flex-wrap: wrap;
    }

    .view-more-link {
      display: inline-flex;
      align-items: center;
      gap: var(--sp-2);
      padding: var(--sp-3) var(--sp-5);
      font-size: 0.9rem;
      font-weight: 700;
      color: var(--brand-purple);
      border: 1.5px solid oklch(50% 0.28 295 / 0.3);
      border-radius: var(--radius-full);
      background: oklch(50% 0.28 295 / 0.05);
      transition: background 0.2s, border-color 0.2s, transform 0.2s;
      white-space: nowrap;
    }

    .view-more-link:hover {
      background: oklch(50% 0.28 295 / 0.1);
      border-color: var(--brand-purple);
      transform: translateY(-1px);
    }

    /* Carousel wrapper */
    .carousel-wrapper {
      position: relative;
    }

    .news-carousel {
      display: flex;
      gap: var(--sp-5);
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding-bottom: var(--sp-4);
      scrollbar-width: thin;
      scrollbar-color: var(--neutral-300) transparent;
      cursor: grab;
    }

    .news-carousel:active { cursor: grabbing; }

    .news-carousel::-webkit-scrollbar {
      height: 4px;
    }

    .news-carousel::-webkit-scrollbar-track { background: transparent; }
    .news-carousel::-webkit-scrollbar-thumb {
      background: var(--neutral-300);
      border-radius: 2px;
    }

    .news-card {
      flex: 0 0 300px;
      scroll-snap-align: start;
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-card);
      transition: transform 0.25s var(--ease-out), box-shadow 0.25s;
    }

    .news-card:hover {
      transform: translateY(-5px);
      box-shadow: var(--shadow-lg);
    }

    .news-thumbnail {
      width: 100%;
      height: 180px;
      position: relative;
      overflow: hidden;
    }

    .news-thumb-bg {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .news-thumb-bg-1 {
      background: linear-gradient(135deg, oklch(50% 0.28 295) 0%, oklch(55% 0.27 330) 100%);
    }

    .news-thumb-bg-2 {
      background: linear-gradient(135deg, oklch(67% 0.21 46) 0%, oklch(60% 0.25 20) 100%);
    }

    .news-thumb-bg-3 {
      background: linear-gradient(135deg, oklch(55% 0.15 200) 0%, oklch(50% 0.28 295) 100%);
    }

    .news-thumb-bg-4 {
      background: linear-gradient(135deg, oklch(40% 0.1 265) 0%, oklch(60% 0.15 220) 100%);
    }

    .news-thumb-icon {
      font-size: 48px;
      opacity: 0.85;
    }

    .news-card-body {
      padding: var(--sp-5);
    }

    .news-tags {
      display: flex;
      flex-wrap: wrap;
      gap: var(--sp-2);
      margin-bottom: var(--sp-3);
    }

    .news-tag {
      display: inline-block;
      padding: 3px 10px;
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      border-radius: var(--radius-full);
    }

    .tag-announcements {
      color: var(--brand-purple);
      background: oklch(50% 0.28 295 / 0.1);
    }

    .tag-tips {
      color: var(--brand-orange);
      background: oklch(67% 0.21 46 / 0.1);
    }

    .tag-product {
      color: oklch(50% 0.2 200);
      background: oklch(50% 0.2 200 / 0.1);
    }

    .tag-safety {
      color: oklch(40% 0.18 160);
      background: oklch(40% 0.18 160 / 0.1);
    }

    .news-title {
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--text-primary);
      line-height: 1.45;
      margin-bottom: var(--sp-3);
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-date {
      font-size: 0.8rem;
      color: var(--text-muted);
      font-weight: 500;
    }

    /* Carousel arrows (desktop) */
    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: var(--bg-card);
      border: 1.5px solid var(--border);
      box-shadow: var(--shadow-md);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      color: var(--text-primary);
      z-index: 2;
      transition: background 0.2s, transform 0.2s var(--ease-out), box-shadow 0.2s;
    }

    .carousel-btn:hover {
      background: var(--neutral-100);
      transform: translateY(-50%) scale(1.06);
      box-shadow: var(--shadow-lg);
    }

    .carousel-btn-prev { left: -22px; }
    .carousel-btn-next { right: -22px; }

    /* =====================================================
       CTA DOWNLOAD SECTION
    ===================================================== */
    .cta-download {
      padding: var(--sp-24) 0;
      background: var(--bg-card);
      text-align: center;
    }

    .cta-download-inner {
      max-width: 560px;
      margin-inline: auto;
    }

    .cta-headline {
      font-size: clamp(2rem, 4vw, 3rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--text-primary);
      line-height: 1.1;
    }

    .cta-subheadline {
      font-size: clamp(1.75rem, 3.5vw, 2.5rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      margin-bottom: var(--sp-8);
    }

    .cta-buttons {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: var(--sp-4);
      flex-wrap: wrap;
    }

    .btn-store {
      display: inline-flex;
      align-items: center;
      gap: var(--sp-3);
      padding: var(--sp-3) var(--sp-6);
      background: var(--brand-black);
      color: #fff;
      border-radius: var(--radius-md);
      font-size: 0.875rem;
      font-weight: 600;
      transition: transform 0.2s var(--ease-out), box-shadow 0.2s;
      box-shadow: var(--shadow-sm);
    }

    .btn-store:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-md);
    }

    .btn-store-icon {
      font-size: 22px;
    }

    .btn-store-text { display: flex; flex-direction: column; line-height: 1.2; text-align: left; }
    .btn-store-pre { font-size: 0.7rem; opacity: 0.75; font-weight: 400; }
    .btn-store-name { font-size: 1rem; font-weight: 700; }

    /* =====================================================
       FOOTER
    ===================================================== */
    .site-footer {
      background: var(--neutral-900);
      color: var(--neutral-300);
      padding-top: var(--sp-16);
    }

    .footer-top {
      display: grid;
      grid-template-columns: 2fr repeat(5, 1fr);
      gap: var(--sp-8);
      padding-bottom: var(--sp-12);
      border-bottom: 1px solid oklch(100% 0 0 / 0.08);
    }

    .footer-brand { padding-right: var(--sp-4); }

    .footer-logo {
      display: flex;
      align-items: center;
      gap: var(--sp-2);
      font-weight: 800;
      font-size: 1.15rem;
      letter-spacing: -0.02em;
      color: #fff;
      margin-bottom: var(--sp-4);
    }

    .footer-tagline {
      font-size: 0.875rem;
      color: var(--neutral-400);
      line-height: 1.65;
      max-width: 220px;
    }

    .footer-col-title {
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: #fff;
      margin-bottom: var(--sp-4);
    }

    .footer-col ul {
      display: flex;
      flex-direction: column;
      gap: var(--sp-3);
    }

    .footer-col a {
      font-size: 0.875rem;
      color: var(--neutral-400);
      transition: color 0.2s;
    }

    .footer-col a:hover { color: #fff; }

    .footer-ext-link {
      display: inline-flex;
      align-items: center;
      gap: 3px;
    }

    .footer-ext-link::after {
      content: '↗';
      font-size: 0.7rem;
      opacity: 0.6;
    }

    .footer-bottom {
      padding: var(--sp-6) 0;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: var(--sp-4);
      flex-wrap: wrap;
    }

    .footer-bottom-left {
      display: flex;
      align-items: center;
      gap: var(--sp-4);
      flex-wrap: wrap;
    }

    .footer-lang {
      display: inline-flex;
      align-items: center;
      gap: var(--sp-2);
      padding: var(--sp-2) var(--sp-3);
      font-size: 0.8rem;
      font-weight: 600;
      color: var(--neutral-300);
      border: 1px solid oklch(100% 0 0 / 0.12);
      border-radius: var(--radius-sm);
      background: oklch(100% 0 0 / 0.04);
      cursor: pointer;
      transition: background 0.2s;
    }

    .footer-lang:hover { background: oklch(100% 0 0 / 0.08); }

    .footer-legal {
      display: flex;
      align-items: center;
      gap: var(--sp-3);
      flex-wrap: wrap;
    }

    .footer-legal a {
      font-size: 0.8rem;
      color: var(--neutral-500);
      transition: color 0.2s;
    }

    .footer-legal a:hover { color: var(--neutral-300); }

    .footer-legal-sep {
      color: var(--neutral-600);
      font-size: 0.8rem;
    }

    /* Social icons */
    .footer-socials {
      display: flex;
      align-items: center;
      gap: var(--sp-2);
    }

    .footer-social-icon {
      width: 34px;
      height: 34px;
      border-radius: var(--radius-sm);
      background: oklch(100% 0 0 / 0.06);
      border: 1px solid oklch(100% 0 0 / 0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
      color: var(--neutral-400);
      transition: background 0.2s, color 0.2s, transform 0.15s;
      cursor: pointer;
    }

    .footer-social-icon:hover {
      background: oklch(100% 0 0 / 0.12);
      color: #fff;
      transform: translateY(-2px);
    }

    /* =====================================================
       RESPONSIVE — TABLET (≤ 1024px)
    ===================================================== */
    @media (max-width: 1024px) {
      .hero-inner { grid-template-columns: 1fr; gap: var(--sp-12); }
      .hero-content { max-width: 100%; text-align: center; }
      .hero-subtitle { margin-inline: auto; }
      .hero-cta-row { justify-content: center; }
      .hero-visual { display: none; }

      .features-grid { grid-template-columns: repeat(2, 1fr); }

      .safety-inner { grid-template-columns: 1fr; gap: var(--sp-10); }
      .safety-visual { order: -1; }

      .creators-inner { grid-template-columns: 1fr; gap: var(--sp-10); }

      .footer-top { grid-template-columns: repeat(3, 1fr); }
      .footer-brand { grid-column: span 3; }
    }

    /* =====================================================
       RESPONSIVE — MOBILE (≤ 768px)
    ===================================================== */
    @media (max-width: 768px) {
      :root { --sp-24: 4rem; --sp-20: 3.5rem; }

      /* Show hamburger, hide desktop nav */
      .hamburger { display: flex; }
      .nav-desktop { display: none; }
      .nav-mobile { display: block; }
      .btn-login { display: none; }

      .hero { padding: var(--sp-16) 0 var(--sp-12); }

      .features-grid { grid-template-columns: 1fr; }

      .safety-visual { grid-template-columns: 1fr; }
      .safety-card:first-child { grid-column: span 1; }

      .creators-stats { grid-template-columns: 1fr; }

      .news-card { flex: 0 0 260px; }
      .carousel-btn { display: none; }

      .footer-top { grid-template-columns: repeat(2, 1fr); row-gap: var(--sp-8); }
      .footer-brand { grid-column: span 2; }

      .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--sp-4);
      }
    }

    @media (max-width: 480px) {
      .footer-top { grid-template-columns: 1fr; }
      .footer-brand { grid-column: span 1; }
      .news-card { flex: 0 0 88vw; }
    }
  </style>
</head>
<body>

  <!-- ===================================================
       HEADER
  =================================================== -->
  <header class="site-header" role="banner">
    <div class="container">
      <div class="header-inner">

        <!-- Logo -->
        <a href="#" class="logo" aria-label="SnapFrame home">
          <span class="logo-icon" aria-hidden="true">
            <svg viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg">
              <path d="M10 2C5.58 2 2 5.58 2 10s3.58 8 8 8 8-3.58 8-8-3.58-8-8-8zm0 3a2 2 0 110 4 2 2 0 010-4zm0 11c-2.21 0-4.17-1.13-5.33-2.85a6.64 6.64 0 0110.66 0C14.17 14.87 12.21 16 10 16z"/>
            </svg>
          </span>
          SnapFrame
        </a>

        <!-- Desktop Navigation -->
        <nav class="nav-desktop" aria-label="Main navigation">
          <a href="#">About</a>
          <a href="#">Features</a>
          <a href="#">Safety</a>
          <a href="#">Creators</a>
          <a href="#">News</a>
        </nav>

        <!-- Header Actions -->
        <div class="header-actions">
          <button class="btn-login">Log in</button>
          <button class="hamburger" id="hamburgerBtn" aria-label="Toggle navigation menu" aria-expanded="false" aria-controls="mobileNav">
            <span></span>
            <span></span>
            <span></span>
          </button>
        </div>

      </div>
    </div>

    <!-- Mobile Navigation -->
    <nav class="nav-mobile" id="mobileNav" aria-label="Mobile navigation">
      <a href="#">About</a>
      <a href="#">Features</a>
      <a href="#">Safety</a>
      <a href="#">Creators</a>
      <a href="#">News</a>
      <button class="btn-login-mobile">Log in</button>
    </nav>
  </header>


  <!-- ===================================================
       HERO
  =================================================== -->
  <section class="hero" aria-label="Hero">
    <div class="container">
      <div class="hero-inner">
        <div class="hero-content">
          <span class="hero-eyebrow">📸 Social Media Platform</span>
          <h1 class="hero-title">
